CREATE TABLE registrations (
    -- Unique ID automatically generated by PostgreSQL
    id BIGSERIAL PRIMARY KEY,

    -- Document information
    document_hash VARCHAR(64) UNIQUE,
    source_filename TEXT,

    -- Vehicle information extracted by Ollama
    plate_number VARCHAR(20) NOT NULL,
    vehicle_type TEXT NOT NULL,

    -- Fees extracted from the OR/CR
    mvuc NUMERIC(12,2) NOT NULL CHECK (mvuc >= 0),
    legal_research_fee NUMERIC(12,2) NOT NULL CHECK (legal_research_fee >= 0),
    penalty NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (penalty >= 0),

    -- Values calculated by n8n
    amount_paid NUMERIC(12,2) NOT NULL CHECK (amount_paid >= 0),
    freelancer_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (freelancer_fee >= 0),

    -- Workflow status
    status VARCHAR(30) NOT NULL DEFAULT 'RECEIVED',

    -- Stores the reason when processing fails or needs review
    error_reason TEXT,

    -- Timestamps
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at TIMESTAMPTZ
);